(function(){angular.module("app.core").directive("hasPermission",function(permissions){return{link:function(scope,element,attrs){if(!angular.isString(attrs.hasPermission)||attrs.hasPermission===""){return}var value=JSON.parse(attrs.hasPermission);var notPermissionFlag=value[0]==="!";
if(notPermissionFlag){value=value.slice(1).trim()}function toggleVisibilityBasedOnPermission(){var hasPermission=permissions.hasPermission(value);if(hasPermission){element.show()}else{element.hide()}}toggleVisibilityBasedOnPermission();scope.$on("permissionsChanged",toggleVisibilityBasedOnPermission)
}}})})();